// Package mind contains a small, non-executing RV Lang plan compiler.
package mind

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var Keywords=[]string{"heal","assemble","evolve","forge","bridge","scan","propose","approve","audit","target","using","with","from","to","if","then","end","let","true","false"}
var commands=map[string]bool{"heal":true,"assemble":true,"evolve":true,"forge":true,"bridge":true,"scan":true,"propose":true,"approve":true,"audit":true}
type Operation struct { Verb string `json:"verb"`; Args []string `json:"args"`; Line int `json:"line"` }
type Result struct { Status string `json:"status"`; Operations []Operation `json:"operations"`; GoSource string `json:"go_source"`; Executed bool `json:"executed"`; HumanApprovalRequired bool `json:"human_approval_required"` }
func Compile(source string)(Result,error){
	if len(source)>64*1024{return Result{},errors.New("RV source exceeds 64 KiB limit")};lines:=strings.Split(source,"\n");ops:=[]Operation{}
	for n,line:=range lines{line=strings.TrimSpace(line);if line==""||strings.HasPrefix(line,"#"){continue};tokens,e:=tokenize(line);if e!=nil{return Result{},fmt.Errorf("line %d: %w",n+1,e)};if len(tokens)==0{continue};verb:=strings.ToLower(tokens[0]);if !commands[verb]{return Result{},fmt.Errorf("line %d: unknown command %q",n+1,verb)};if verb!="scan"&&len(tokens)<2{return Result{},fmt.Errorf("line %d: command %s requires an argument",n+1,verb)};ops=append(ops,Operation{Verb:verb,Args:tokens[1:],Line:n+1});if len(ops)>200{return Result{},errors.New("RV program exceeds 200 operations")}}
	if len(ops)==0{return Result{},errors.New("RV source contains no operations")};var b strings.Builder;b.WriteString("// Code generated by USECT-ZERO RV compiler; review required. DO NOT execute as an authorization mechanism.\npackage main\n\ntype Operation struct { Verb string; Args []string; Line int }\n\nvar Plan = []Operation{\n")
	for _,op:=range ops{args:=make([]string,len(op.Args));for i,a:=range op.Args{args[i]=strconv.Quote(a)};b.WriteString(fmt.Sprintf("  {Verb: %s, Args: []string{%s}, Line: %d},\n",strconv.Quote(op.Verb),strings.Join(args,", "),op.Line))};b.WriteString("}\n");return Result{Status:"plan_generated_pending_review",Operations:ops,GoSource:b.String(),Executed:false,HumanApprovalRequired:true},nil
}
func tokenize(s string)([]string,error){
	var out []string;var b strings.Builder;var quote rune;escaped:=false;active:=false
	for _,r:=range s{if escaped{b.WriteRune(r);escaped=false;active=true;continue};if quote!=0{if r=='\\'{escaped=true;continue};if r==quote{quote=0;active=true}else{b.WriteRune(r)};continue};if r=='\''||r=='"'{quote=r;active=true;continue};if r==' '||r=='\t'||r=='\r'{if active{out=append(out,b.String());b.Reset();active=false};continue};b.WriteRune(r);active=true}
	if escaped||quote!=0{return nil,errors.New("unterminated quoted string or escape")};if active{out=append(out,b.String())};return out,nil
}
